    private TabelasGs1() {
    }

    /**
     * Um componente de um AI: o tipo, e o comprimento como par fixo/maximo.
     *
     * <p><b>Um dos dois e' sempre nulo</b>, e e' assim que se distingue um campo
     * de comprimento fixo de um variavel sem um booleano a mais. **Um campo
     * que aceite os dois nao se sabe ler** - o AI `3103` e' um campo fixo de
     * tres digitos mais um campo variavel, e nao um campo fixo de quatro.
     */
    public record Componente(String tipo, Integer fixo, Integer maximo) {
    }

    /**
     * Um AI, com tudo o que o encoder precisa dele.
     *
     * <p>{@code separador} diz se o campo precisa de um FNC1 a separa-lo do
     * seguinte. <b>E' a razao de existir esta tabela</b>: sem ela nao se sabe
     * onde acaba {@code (10)LOTE-A1} e onde comeca o campo seguinte.
     */
    public record Ai(
            String numero,
            String formato,
            Integer fixo,
            Integer maximo,
            List<Componente> campos,
            boolean separador,
            String regex,
            String resto) {

        /**
         * O mesmo AI, com o numero efectivo e o que sobrou do campo.
         *
         * <p><b>Os dois so' existem na procura</b>, e e' por isso que ficam
         * no registo em vez de no mapa: um AI procurado directamente tem
         * {@code resto} nulo, e a forma de o dizer e' o proprio nulo.
         */
        public Ai buscado(String numeroEfectivo, String restoEfectivo) {
            return new Ai(numeroEfectivo, formato, fixo, maximo, campos, separador,
                regex, restoEfectivo);
        }
    }

